'use client';

import { useRouter } from 'next/navigation';
import React, { useMemo, useState } from 'react';

import BranchMapPickerYandex from './BranchMapPickerYandex';

import { AlertBanner } from '@/components/ui/AlertBanner';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { Input } from '@/components/ui/Input';


type Props = {
    mode: 'create' | 'edit';
    bizId: string;
    branchId?: string;
    yandexMapsApiKey?: string;
    initial?: { name: string; address: string; is_active: boolean; lat?: number | null; lon?: number | null; directory_links?: Record<string, string | null>; contact_phone?: string | null; contact_whatsapp?: string | null; contact_email?: string | null; website_url?: string | null; inherit_business_contacts?: boolean | null };
};

type ApiOk = { ok: true; id?: string };
type ApiErr = { ok: false; error?: string };
type ApiResp = ApiOk | ApiErr;

export function BranchForm({ mode, bizId, branchId, yandexMapsApiKey, initial }: Props) {
    const router = useRouter();

    const [name, setName] = useState<string>(initial?.name ?? '');
    const [address, setAddress] = useState<string>(initial?.address ?? '');
    const [isActive, setIsActive] = useState<boolean>(initial?.is_active ?? true);
    const [lat, setLat] = useState<number | null>(initial?.lat ?? null);
    const [lon, setLon] = useState<number | null>(initial?.lon ?? null);
    const [links, setLinks] = useState({
        instagram: initial?.directory_links?.instagram ?? '',
        two_gis: initial?.directory_links?.two_gis ?? '',
        google_maps: initial?.directory_links?.google_maps ?? '',
        yandex_maps: initial?.directory_links?.yandex_maps ?? '',
    });
    const [contacts, setContacts] = useState({
        contact_phone: initial?.contact_phone ?? '',
        contact_whatsapp: initial?.contact_whatsapp ?? '',
        contact_email: initial?.contact_email ?? '',
        website_url: initial?.website_url ?? '',
    });
    const [inheritBusinessContacts, setInheritBusinessContacts] = useState(initial?.inherit_business_contacts !== false);

    const [err, setErr] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);

    const changed = useMemo(() => {
        if (mode === 'create') return true;
        return (
            name !== (initial?.name ?? '') ||
            address !== (initial?.address ?? '') ||
            isActive !== (initial?.is_active ?? true) ||
            lat !== (initial?.lat ?? null) ||
            lon !== (initial?.lon ?? null) ||
            links.instagram !== (initial?.directory_links?.instagram ?? '') ||
            links.two_gis !== (initial?.directory_links?.two_gis ?? '') ||
            links.google_maps !== (initial?.directory_links?.google_maps ?? '') ||
            links.yandex_maps !== (initial?.directory_links?.yandex_maps ?? '') ||
            contacts.contact_phone !== (initial?.contact_phone ?? '') ||
            contacts.contact_whatsapp !== (initial?.contact_whatsapp ?? '') ||
            contacts.contact_email !== (initial?.contact_email ?? '') ||
            contacts.website_url !== (initial?.website_url ?? '') ||
            inheritBusinessContacts !== (initial?.inherit_business_contacts !== false)
        );
    }, [mode, name, address, isActive, lat, lon, links, contacts, inheritBusinessContacts, initial]);

    function extractError(e: unknown): string {
        return e instanceof Error ? e.message : String(e);
    }

    async function submit(e: React.FormEvent<HTMLFormElement>) {
        e.preventDefault();
        setErr(null);
        setLoading(true);
        try {
            const trimmedName = name.trim();
            if (!trimmedName) throw new Error('Название филиала обязательно');

            const url =
                mode === 'create'
                    ? `/admin/api/businesses/${bizId}/branches/create`
                    : `/admin/api/businesses/${bizId}/branches/${branchId}/update`;

            const body = {
                name: trimmedName,
                address: address.trim() || null,
                is_active: isActive,
                lat, lon,
                directory_links: links,
                ...contacts,
                inherit_business_contacts: inheritBusinessContacts,
            };

            const resp = await fetch(url, {
                method: 'POST',
                headers: { 'content-type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify(body),
            });

            const ct = resp.headers.get('content-type') ?? '';
            let data: ApiResp | null = null;
            if (ct.includes('application/json')) data = (await resp.json()) as ApiResp;
            else {
                const text = await resp.text();
                if (!resp.ok) throw new Error(text.slice(0, 2000));
                data = { ok: true };
            }

            if (!resp.ok || !('ok' in data) || !data.ok) {
                const apiErr = (data && 'error' in data ? (data as ApiErr).error : undefined) ?? `HTTP ${resp.status}`;
                throw new Error(apiErr);
            }

            router.push(`/admin/businesses/${bizId}/branches`);
            router.refresh();
        } catch (e) {
            setErr(extractError(e));
        } finally {
            setLoading(false);
        }
    }

    return (
        <form onSubmit={submit} className="space-y-6 max-w-2xl">
            <Input
                label="Название филиала"
                placeholder="Введите название филиала"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
                name="branch_name"
                error={err && !name.trim() ? 'Название филиала обязательно' : undefined}
            />

            {/* Карта Яндекса */}
            <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
                    Расположение на карте
                </label>
                <Card className="p-4">
                    <BranchMapPickerYandex
                        yandexMapsApiKey={yandexMapsApiKey}
                        lat={lat ?? undefined}
                        lon={lon ?? undefined}
                        onPick={(la, lo, addr) => {
                            setLat(la);
                            setLon(lo);
                            if (addr) setAddress(addr); // адрес заполняется только через карту
                        }}
                    />
                    <div className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                        Координаты: {lat ? lat.toFixed(6) : '—'}, {lon ? lon.toFixed(6) : '—'}
                    </div>
                    <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                        Кликните на карте, чтобы установить метку. Адрес заполнится автоматически.
                    </p>
                </Card>
            </div>

            <Input
                label="Адрес"
                placeholder="Адрес будет заполнен автоматически при выборе на карте"
                value={address}
                name="branch_address"
                autoComplete="street-address"
                helperText="Адрес можно выбрать на карте или ввести вручную"
            />

            <div className="space-y-3 rounded-xl border border-gray-200 p-4 dark:border-gray-700">
                <div>
                    <p className="text-sm font-medium text-gray-900 dark:text-gray-100">Ссылки филиала</p>
                    <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">Эти ссылки будут видны клиентам на публичной странице бизнеса.</p>
                </div>
                <div className="grid gap-3 sm:grid-cols-2">
                    {([
                        ['instagram', 'Instagram', 'https://instagram.com/...'],
                        ['two_gis', '2ГИС', 'https://2gis.ru/...'],
                        ['google_maps', 'Google Карты', 'https://maps.google.com/...'],
                        ['yandex_maps', 'Яндекс Карты', 'https://yandex.ru/maps/...'],
                    ] as const).map(([key, label, placeholder]) => (
                        <Input key={key} label={label} type="url" placeholder={placeholder} value={links[key]} onChange={(e) => setLinks((current) => ({ ...current, [key]: e.target.value }))} />
                    ))}
                </div>
            </div>

            <div className="space-y-4 rounded-xl border border-gray-200 p-4 dark:border-gray-700">
                <div>
                    <p className="text-sm font-medium text-gray-900 dark:text-gray-100">Публичные контакты филиала</p>
                    <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                        Эти данные принадлежат бизнесу. Личные телефоны владельцев и сотрудников здесь не используются.
                    </p>
                </div>
                <label className="flex items-start gap-3 text-sm text-gray-700 dark:text-gray-300">
                    <input
                        type="checkbox"
                        checked={inheritBusinessContacts}
                        onChange={(event) => setInheritBusinessContacts(event.target.checked)}
                        className="mt-0.5 h-4 w-4 rounded"
                    />
                    <span>
                        Использовать контакты бизнеса для незаполненных полей
                        <span className="mt-1 block text-xs text-gray-500 dark:text-gray-400">
                            Контакт филиала всегда имеет приоритет.
                        </span>
                    </span>
                </label>
                <div className="grid gap-3 sm:grid-cols-2">
                    <Input label="Телефон" type="tel" placeholder="+996..." value={contacts.contact_phone} onChange={(e) => setContacts((value) => ({ ...value, contact_phone: e.target.value }))} />
                    <Input label="WhatsApp" type="tel" placeholder="+996..." value={contacts.contact_whatsapp} onChange={(e) => setContacts((value) => ({ ...value, contact_whatsapp: e.target.value }))} />
                    <Input label="Публичный email" type="email" placeholder="hello@business.kg" value={contacts.contact_email} onChange={(e) => setContacts((value) => ({ ...value, contact_email: e.target.value }))} />
                    <Input label="Сайт" type="url" placeholder="https://..." value={contacts.website_url} onChange={(e) => setContacts((value) => ({ ...value, website_url: e.target.value }))} />
                </div>
            </div>

            <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-gray-900 rounded-lg border border-gray-200 dark:border-gray-700">
                <input
                    type="checkbox"
                    id="is_active"
                    checked={isActive}
                    onChange={(e) => setIsActive(e.target.checked)}
                    className="w-4 h-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500 focus:ring-2"
                />
                <label htmlFor="is_active" className="text-sm font-medium text-gray-700 dark:text-gray-300 cursor-pointer">
                    Филиал активен
                </label>
                <p className="text-xs text-gray-500 dark:text-gray-400 ml-auto">
                    {isActive ? 'Филиал будет отображаться в публичном каталоге' : 'Филиал скрыт от пользователей'}
                </p>
            </div>

            {err ? <AlertBanner variant="danger" message={err} /> : null}

            <div className="flex items-center gap-3 pt-4">
                <Button
                    type="submit"
                    disabled={loading || (mode === 'edit' && !changed)}
                    isLoading={loading}
                    className="min-w-[160px]"
                >
                    {mode === 'create' ? 'Создать филиал' : 'Сохранить изменения'}
                </Button>
                {mode === 'edit' && !changed && (
                    <span className="text-sm text-gray-500 dark:text-gray-400">Нет изменений для сохранения</span>
                )}
            </div>
        </form>
    );
}
